#!/bin/sh
# Downloads and converts the host-provided module data tables into data/.
# Mirrors the macOS host's pipeline (same pinned sources, same conversion):
# wordFrequency is the single-character subset of McBopomofo's phrase.occ
# corpus (MIT). Generated files are not committed; dev-install.sh installs
# them alongside the addon.
set -eu

root="$(cd "$(dirname "$0")/.." && pwd)"
out_dir="$root/data/modules"
mkdir -p "$out_dir"

mcbopomofo_pin="20d86c571d183a7ce7d5f91419b815dea5c3efbc"
occ_url="https://raw.githubusercontent.com/openvanilla/McBopomofo/$mcbopomofo_pin/Source/Data/phrase.occ"
license_url="https://raw.githubusercontent.com/openvanilla/McBopomofo/$mcbopomofo_pin/LICENSE.txt"

occ_file="$root/data/phrase.occ"
if [ ! -f "$occ_file" ]; then
    echo "Downloading phrase.occ ($mcbopomofo_pin)..."
    curl -fsSL "$occ_url" -o "$occ_file"
fi
if [ ! -f "$root/data/McBopomofo.LICENSE.txt" ]; then
    curl -fsSL "$license_url" -o "$root/data/McBopomofo.LICENSE.txt"
fi

python3 - "$occ_file" "$out_dir/wordFrequency.zh-Hant.tsv" "$occ_url" <<'EOF'
import sys

occ_path, out_path, source_url = sys.argv[1:4]
lines = [
    "# Per-character frequency table (single-character subset of the source corpus).",
    "# format: char<TAB>count",
    f"# source: {source_url}",
    "# generated by scripts/prepare-data.sh - DO NOT EDIT",
    "",
]
with open(occ_path, encoding="utf-8") as occ:
    for line in occ:
        parts = line.split(None, 1)
        if len(parts) != 2:
            continue
        key, count = parts[0], parts[1].strip()
        if len(key) == 1:  # exactly one Unicode scalar
            lines.append(f"{key}\t{count}")
with open(out_path, "w", encoding="utf-8") as out:
    out.write("\n".join(lines) + "\n")
print(f"wrote {out_path} ({len(lines) - 5} entries)")
EOF
